import type { BankQuestion } from "@/lib/bank";

/** Biomolecules and Enzymes (Biology (NEET)): 100 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-biomolecules-enzymes-1","question":"The most abundant protein in the animal world is:","options":["Collagen","Haemoglobin","Keratin","RuBisCO"],"answer":0,"explanation":"Collagen is the most abundant protein in the animal world; RuBisCO (ribulose bisphosphate carboxylase-oxygenase) is the most abundant protein in the whole biosphere.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-2","question":"The bond that links two monosaccharides in a polysaccharide is a:","options":["Peptide bond","Phosphodiester bond","Glycosidic bond","Ester bond"],"answer":2,"explanation":"Monosaccharides are joined by glycosidic bonds; amino acids by peptide bonds; nucleotides by phosphodiester bonds; fatty acids and glycerol by ester bonds.","difficulty":"easy"},
  {"id":"bio-biomolecules-enzymes-3","question":"Which enzyme catalyses the reaction CO₂ + H₂O → H₂CO₃ at very high speed?","options":["Carbonic anhydrase","Catalase","Carboxypeptidase","Succinic dehydrogenase"],"answer":0,"explanation":"Carbonic anhydrase accelerates the hydration of CO₂ about 10 million times: one enzyme molecule can form about 600,000 molecules of carbonic acid per second.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-4","question":"Enzymes that remove groups from substrates by mechanisms other than hydrolysis, leaving a double bond, belong to the class:","options":["Hydrolases","Isomerases","Lyases","Ligases"],"answer":2,"explanation":"Lyases catalyse removal of groups without hydrolysis, leaving double bonds (or add groups to double bonds). Hydrolases use water; isomerases interconvert isomers; ligases join two molecules using ATP.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-5","question":"The Michaelis constant (Km) of an enzyme is the substrate concentration at which:","options":["The reaction velocity is maximum","The enzyme is fully saturated","All the enzyme is denatured","The reaction velocity is half of Vmax"],"answer":3,"explanation":"Km is the substrate concentration at which the reaction attains half its maximum velocity. A low Km means high affinity for the substrate.","difficulty":"moderate"},
  {"id":"bio-biomolecules-enzymes-6","question":"Lecithin is an example of a:","options":["Phospholipid","Simple triglyceride","Steroid","Wax"],"answer":0,"explanation":"Lecithin is a phospholipid (glycerol, fatty acids and a phosphorylated organic group) found in cell membranes.","difficulty":"moderate"},
  {"id":"bio-biomolecules-enzymes-7","question":"Which of the following is a primary metabolite?","options":["Morphine","Ricin","Glucose","Vinblastin"],"answer":2,"explanation":"Primary metabolites (amino acids, sugars, nucleotides, lipids) have identifiable roles in normal physiology. Morphine (alkaloid), ricin (toxin) and vinblastin (drug) are secondary metabolites.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-8","question":"Adenosine differs from adenylic acid in that adenosine lacks:","options":["The nitrogenous base","The pentose sugar","The phosphate group","Both sugar and phosphate"],"answer":2,"explanation":"A nucleoside is base + sugar (adenosine); a nucleotide is base + sugar + phosphate (adenylic acid). Nucleotides, not nucleosides, polymerise into nucleic acids.","difficulty":"moderate"},
  {"id":"bio-biomolecules-enzymes-9","question":"Which amino acid is classified as basic on the basis of its R group?","options":["Glutamic acid","Lysine","Valine","Tyrosine"],"answer":1,"explanation":"Lysine is basic; glutamic acid is acidic; valine is neutral; tyrosine, phenylalanine and tryptophan are aromatic amino acids.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-10","question":"Starch gives a blue colour with iodine but cellulose does not because:","options":["Cellulose contains fructose","Starch is a homopolymer of galactose","Cellulose is a heteropolymer","Starch forms helical secondary structures that hold I₂, cellulose does not form complex helices"],"answer":3,"explanation":"Starch forms helices that can hold iodine molecules, producing the blue colour. Cellulose, though also a glucose polymer, forms no complex helices and so cannot hold I₂.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-11","question":"Arachidonic acid contains how many carbon atoms, including the carboxyl carbon?","options":["16","18","20","22"],"answer":2,"explanation":"Arachidonic acid has 20 carbons including the carboxyl carbon; palmitic acid has 16. Fatty acids may be saturated or unsaturated (with one or more C=C bonds).","difficulty":"hard"},
  {"id":"bio-biomolecules-enzymes-12","question":"In competitive inhibition of succinic dehydrogenase by malonate, which of the following is true?","options":["Vmax is unchanged and apparent Km increases","Vmax decreases and Km is unchanged","Both Vmax and Km decrease","Both Vmax and Km are unchanged"],"answer":0,"explanation":"A competitive inhibitor resembles the substrate (malonate resembles succinate) and competes for the active site. It can be overcome by excess substrate, so Vmax is unchanged while the apparent Km rises.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-13","question":"The coenzymes NAD and NADP contain which vitamin as an essential component?","options":["Riboflavin","Thiamine","Niacin","Pyridoxine"],"answer":2,"explanation":"NAD and NADP contain niacin (vitamin B₃); co-enzymes are organic cofactors whose association with the apoenzyme is transient and many are vitamin-derived.","difficulty":"hard"},
  {"id":"bio-biomolecules-enzymes-14","question":"Although lipids are small molecules of relatively low molecular weight, they are found in the acid-insoluble fraction of a tissue extract because:","options":["Lipids are polymers of fatty acids","Lipids have very high melting points","Lipids bind covalently to proteins","Lipids are present as membranes that break into vesicles which are not water-soluble"],"answer":3,"explanation":"Lipids occur as cell membranes; on grinding, membranes form vesicles that are insoluble in water and sediment with the macromolecular fraction, so lipids are counted there despite their small size.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-15","question":"At low temperature an enzyme is:","options":["Preserved in a temporarily inactive state","Permanently denatured","Converted to its prosthetic group","Hydrolysed to amino acids"],"answer":0,"explanation":"Low temperature preserves the enzyme in a temporarily inactive state; high temperature destroys activity by denaturing the protein. The rate roughly doubles for every 10 °C rise until the optimum.","difficulty":"hard"},
  {"id":"bio-biomolecules-enzymes-16","question":"The reaction catalysed by an enzyme proceeds through a transition state. The enzyme increases the rate because it:","options":["Raises the energy of the product","Lowers the activation energy barrier","Changes the free energy difference between substrate and product","Shifts the equilibrium towards the product"],"answer":1,"explanation":"An enzyme lowers the activation energy needed to reach the transition state. It does not alter the overall free energy change or the position of equilibrium, only the speed of reaching it.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-17","question":"Inulin, a storage polysaccharide, is a polymer of:","options":["Glucose","N-acetyl glucosamine","Galactose","Fructose"],"answer":3,"explanation":"Inulin is a polymer of fructose. Starch, glycogen and cellulose are glucose polymers; chitin is made of N-acetyl glucosamine units.","difficulty":"hard"},
  {"id":"bio-biomolecules-enzymes-18","question":"Which pair of enzyme and its cofactor type is correctly matched?","options":["Carboxypeptidase: haem as prosthetic group","Catalase: zinc as metal ion","Peroxidase: haem as prosthetic group","Succinic dehydrogenase: niacin as prosthetic group"],"answer":2,"explanation":"Haem is the prosthetic group of peroxidase and catalase; zinc is the metal-ion cofactor of carboxypeptidase; NAD (niacin-containing) is a coenzyme, not a prosthetic group.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-19","question":"How many of the following statements about enzymes are correct?\n(i) All enzymes are proteins.\n(ii) Enzymes alter the equilibrium of a reaction in favour of the product.\n(iii) Enzymes are classified into six classes, each with 4 to 13 subclasses.\n(iv) Enzymes from thermophilic organisms remain stable at high temperatures.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(iii) and (iv) are correct. (i) is false because some nucleic acids act as enzymes (ribozymes); (ii) is false because enzymes only speed up attainment of equilibrium.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-20","question":"Match the enzyme class with the reaction it catalyses.\nList I: (A) Oxidoreductase (B) Transferase (C) Isomerase (D) Ligase\nList II: (1) Transfer of a group between a pair of substrates (2) Linking two compounds using energy (3) Oxidation of one substrate with reduction of another (4) Interconversion of optical, geometric or positional isomers","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-2, B-1, C-4, D-3"],"answer":0,"explanation":"Oxidoreductases handle paired oxidation-reduction, transferases move groups (G) between substrates, isomerases interconvert isomers, ligases join two molecules (usually with ATP).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-21","question":"For an enzyme obeying Michaelis-Menten kinetics with Km = 4 mM, the reaction velocity at a substrate concentration of 12 mM is:","options":["0.25 Vmax","0.50 Vmax","0.75 Vmax","Vmax"],"answer":2,"explanation":"V = Vmax × [S]/(Km + [S]) = Vmax × 12/(4 + 12) = 12/16 Vmax = 0.75 Vmax. At [S] = Km the velocity would be exactly 0.5 Vmax.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-22","question":"Assertion (A): An apoenzyme alone is catalytically inactive.\nReason (R): Removal of the cofactor from a holoenzyme abolishes its catalytic activity, showing the cofactor is essential.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. The protein part (apoenzyme) needs its cofactor (prosthetic group, coenzyme or metal ion) for activity; together they form the holoenzyme.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-23","question":"Which pair of protein and function is INCORRECTLY matched?","options":["Collagen: intercellular ground substance","GLUT-4: enables glucose transport into cells","Trypsin: hormone","Antibody: fights infectious agents"],"answer":2,"explanation":"Trypsin is an enzyme; insulin is the hormone in the NCERT list. Collagen, GLUT-4, antibody and receptor (sensory reception) are correctly matched.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-24","question":"How many of the following statements about nucleic acids are correct?\n(i) Adenine and guanine are substituted purines; cytosine, uracil and thymine are substituted pyrimidines.\n(ii) Uracil is found in RNA in place of thymine.\n(iii) The sugar in DNA is 2'-deoxyribose.\n(iv) Adjacent nucleotides are linked by phosphodiester bonds.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four statements are correct descriptions of nucleic acid chemistry from NCERT.","difficulty":"very-hard"},
  {"id":"bio-biomolecules-enzymes-25","question":"Match the secondary metabolite with its class.\nList I: (A) Abrin (B) Concanavalin A (C) Curcumin (D) Anthocyanin\nList II: (1) Pigment (2) Drug (3) Lectin (4) Toxin","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Abrin and ricin are toxins; concanavalin A is a lectin; vinblastin and curcumin are drugs; carotenoids and anthocyanins are pigments.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-26","question":"Which statement about polysaccharides is INCORRECT?","options":["Glycogen is a branched homopolymer of glucose","Cellulose is an unbranched homopolymer of glucose","The right end of a polysaccharide chain is the non-reducing end","Chitin is a complex polysaccharide of arthropod exoskeletons"],"answer":2,"explanation":"NCERT designates the right end of a polysaccharide chain (e.g., glycogen) as the reducing end and the left end as the non-reducing end, so option 3 reverses it. The other three statements are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-27","question":"How many of the following statements about metabolism are correct?\n(i) Metabolic pathways may be linear or circular.\n(ii) Anabolic pathways consume energy while catabolic pathways release it.\n(iii) The living state is a non-equilibrium steady state.\n(iv) Energy released in catabolism is stored as ATP.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are NCERT statements: pathways are linear or circular, anabolism costs energy, catabolism (e.g., glucose to lactic acid) releases energy stored as ATP, and living systems are never at equilibrium.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-28","question":"Which of the following correctly describes the R groups of glycine, alanine and serine respectively?","options":["H, CH₃, CH₂OH","CH₃, H, CH₂OH","H, CH₂OH, CH₃","CH₂OH, CH₃, H"],"answer":0,"explanation":"Glycine has hydrogen as its R group, alanine a methyl group and serine a hydroxymethyl group. The R group decides the amino acid's chemical and physical nature.","difficulty":"very-hard"},
  {"id":"bio-biomolecules-enzymes-29","question":"Assertion (A): A plot of reaction velocity against substrate concentration for an enzyme-catalysed reaction is a rectangular hyperbola that reaches a plateau.\nReason (R): At high substrate concentration no free enzyme molecules are available to bind additional substrate.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: the velocity rises with [S] until all active sites are occupied; then the rate (Vmax) cannot increase further, giving the plateau.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-30","question":"Which statement about protein structure is INCORRECT?","options":["Primary structure is the sequence of amino acids with the first amino acid at the N-terminal","The helix of secondary structure is right-handed","Tertiary structure is the three-dimensional folding of a single polypeptide","Haemoglobin shows tertiary but not quaternary structure"],"answer":3,"explanation":"Adult human haemoglobin is made of four polypeptide chains (two α and two β), so it has quaternary structure. The first three statements are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-31","question":"Which nitrogenous base is found in RNA but not in DNA?","options":["Thymine","Uracil","Adenine","Cytosine"],"answer":1,"explanation":"RNA contains uracil in place of the thymine of DNA; adenine, guanine and cytosine are common to both.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-32","question":"By convention, the first amino acid at the left end of a written polypeptide is called the:","options":["N-terminal amino acid","Reducing end","C-terminal amino acid","Non-reducing end"],"answer":0,"explanation":"A protein is imagined as a line whose left end is the first amino acid (N-terminal) and right end the last amino acid (C-terminal). Reducing ends describe polysaccharides.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-33","question":"The most abundant protein in the whole of the biosphere is:","options":["Collagen","RuBisCO","Haemoglobin","Keratin"],"answer":1,"explanation":"Ribulose bisphosphate carboxylase-oxygenase (RuBisCO) is the most abundant protein in the biosphere; collagen is the most abundant protein in the animal world.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-34","question":"Amino acids can exist in different ionic forms (including zwitterions) at different pH values because:","options":["They contain a phosphate group","Both the amino and carboxyl groups are ionizable","Their R group is always a hydrocarbon chain","They have no charged groups at all"],"answer":1,"explanation":"The ionizable –NH₂ and –COOH groups make the structure of an amino acid change in solutions of different pH.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-35","question":"Carboxypeptidase, a proteolytic enzyme, requires which metal ion as a cofactor?","options":["Copper","Zinc","Magnesium","Iron"],"answer":1,"explanation":"Zinc is a cofactor of carboxypeptidase. Haem (with iron) is the prosthetic group of peroxidase and catalase.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-36","question":"In a nucleoside, the nitrogenous base is attached to the sugar by:","options":["An ester bond with phosphate","A peptide bond","An N-glycosidic linkage","A phosphodiester bond"],"answer":2,"explanation":"Base + sugar (N-glycosidic link) gives a nucleoside; esterifying the sugar's –OH with phosphate gives a nucleotide; nucleotides are joined by 3'–5' phosphodiester bonds.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-37","question":"The living state is best described as:","options":["A state in which metabolism stops","A state of chemical equilibrium","A non-equilibrium steady state that can perform work","A state in which no energy input is needed"],"answer":2,"explanation":"Systems at equilibrium cannot perform work. Living organisms stay in a non-equilibrium steady state through metabolism, which provides the energy needed.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-38","question":"Enzymes isolated from organisms living in very high temperatures, such as hot vents and sulphur springs, are:","options":["Stable and retain catalytic power even at 80–90 °C","Denatured above 40 °C like most enzymes","Non-protein in nature","Active only at temperatures near 0 °C"],"answer":0,"explanation":"Thermophilic organisms have thermostable enzymes that keep their activity at 80–90 °C; such enzymes, like Taq polymerase, are valuable in biotechnology.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-39","question":"How many of the following statements about amino acids are correct?\n(i) There are 20 types of amino acids found in proteins.\n(ii) Glutamic acid is an acidic amino acid.\n(iii) Tyrosine, phenylalanine and tryptophan are aromatic amino acids.\n(iv) Glycine is an essential amino acid that must be supplied through the diet.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. Glycine is a non-essential amino acid; essential amino acids are those our body cannot make.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-40","question":"Match the protein with its function.\nList I: (A) Antibody (B) Receptor (C) Collagen (D) GLUT-4\nList II: (1) Enables glucose transport into cells (2) Intercellular ground substance (3) Sensory reception (smell, taste, hormones) (4) Fights infectious agents","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"answer":1,"explanation":"Antibodies fight infectious agents, receptors mediate sensory reception, collagen is the intercellular ground substance and GLUT-4 transports glucose into cells.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-41","question":"Assertion (A): Ribozymes are nucleic acids that behave like enzymes.\nReason (R): All enzymes are proteins.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true but R is false: almost all enzymes are proteins, but some nucleic acids (ribozymes), such as the rRNA catalysing peptide bond formation, act as enzymes.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-42","question":"Which pair consists only of homopolymers?","options":["Cellulose and inulin","Insulin and starch","Glycogen and haemoglobin","DNA and cellulose"],"answer":0,"explanation":"Cellulose (glucose) and inulin (fructose) are each built from one kind of monomer. Insulin and haemoglobin are heteropolymers of different amino acids, and DNA is built from four different nucleotides.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-43","question":"How many of the following statements about metabolism are correct?\n(i) Conversion of glucose to lactic acid in skeletal muscle takes place in 10 metabolic steps catalysed by different enzymes.\n(ii) Under normal aerobic conditions, glucose is first converted to pyruvic acid.\n(iii) In yeast, during fermentation, glucose yields ethanol.\n(iv) ATP is the most important form of energy currency in living systems.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct NCERT statements; metabolic pathways are linked, each step catalysed by a specific enzyme.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-44","question":"Arrange the following in increasing order of the number of carbon atoms: palmitic acid, ribose, arachidonic acid, glucose.","options":["Glucose < ribose < palmitic acid < arachidonic acid","Ribose < palmitic acid < glucose < arachidonic acid","Ribose < glucose < palmitic acid < arachidonic acid","Ribose < glucose < arachidonic acid < palmitic acid"],"answer":2,"explanation":"Ribose has 5 C, glucose 6 C, palmitic acid 16 C and arachidonic acid 20 C (both fatty acids counted including the carboxyl carbon).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-45","question":"Assertion (A): Enzymes lose their activity at high temperatures.\nReason (R): Heat destroys the tertiary structure of the protein, and with it the active site.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: the active site depends on the three-dimensional (tertiary) folding of the enzyme, which heat disrupts (denaturation). Low temperature only inactivates the enzyme temporarily.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-biomolecules-enzymes-46", "question": "Cellulose, the main constituent of the plant cell wall, is a polymer of:", "options": ["Fructose", "Glucose", "Galactose", "Ribose"], "answer": 1, "explanation": "Cellulose is a homopolymer of glucose. Inulin is the polymer of fructose, a common trap.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-47", "question": "The exoskeleton of arthropods contains a complex polysaccharide called:", "options": ["Cellulose", "Chitin", "Starch", "Glycogen"], "answer": 1, "explanation": "Arthropod exoskeletons have chitin, a complex polysaccharide built of chemically modified sugars (amino-sugars). Cellulose is in plant cell walls and glycogen is the animal storage polysaccharide.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-48", "question": "To analyse the chemical composition of a tissue, it is ground in trichloroacetic acid and strained. The filtrate obtained is called the:", "options": ["Acid-insoluble fraction", "Retentate", "Acid-soluble pool", "Ash"], "answer": 2, "explanation": "Grinding in trichloroacetic acid (Cl₃CCOOH) gives a thick slurry; the filtrate is the acid-soluble pool and the material left behind is the retentate or acid-insoluble fraction.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-49", "question": "Oils such as gingelly oil remain liquid in winter because they:", "options": ["Have a higher melting point than fats", "Have a lower melting point than fats", "Contain no fatty acids", "Are polymers of glucose"], "answer": 1, "explanation": "NCERT notes that oils have a lower melting point and hence remain as oil in winters. They are still lipids made of fatty acids and glycerol.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-50", "question": "Enzymes that catalyse the hydrolysis of ester, ether, peptide, glycosidic, C-C, C-halide or P-N bonds belong to the class:", "options": ["Lyases", "Transferases", "Ligases", "Hydrolases"], "answer": 3, "explanation": "Hydrolases catalyse hydrolysis of these bonds. Lyases remove groups by non-hydrolytic means, leaving double bonds; ligases join two compounds.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-51", "question": "When a living tissue is burnt completely, all the carbon compounds are oxidised to gaseous form. The remaining ash contains:", "options": ["Proteins and nucleic acids", "Inorganic elements such as calcium and magnesium", "Only lipids", "Only carbohydrates"], "answer": 1, "explanation": "Burning removes carbon compounds as gases (CO₂, water vapour); the ash contains inorganic elements such as calcium and magnesium. Inorganic compounds such as sulphate and phosphate are also seen in the acid-soluble fraction.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-52", "question": "A protein is described as a heteropolymer because:", "options": ["It contains glucose and fructose", "It is made of different types of amino acids", "It contains both DNA and RNA", "It has only one kind of monomer repeated many times"], "answer": 1, "explanation": "Proteins are linear chains of amino acids joined by peptide bonds, and since 20 different amino acids occur, a protein is a heteropolymer. A homopolymer, like cellulose, has only one kind of monomer.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-53", "question": "Haem is the prosthetic group of which pair of enzymes, which break down hydrogen peroxide to water and oxygen?", "options": ["Peroxidase and catalase", "Pepsin and trypsin", "Amylase and lipase", "Carboxypeptidase and carbonic anhydrase"], "answer": 0, "explanation": "In peroxidase and catalase, haem is the tightly bound prosthetic group forming part of the active site. Carboxypeptidase needs zinc, a metal ion cofactor.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-54", "question": "According to NCERT, the concentration of glucose in the blood of a normal healthy individual is about:", "options": ["0.45–0.50 mM", "4.5–5.0 mM", "45–50 mM", "450–500 mM"], "answer": 1, "explanation": "Blood glucose in a healthy person is 4.5–5.0 mM, whereas hormones are present in nanograms per mL. The other options are off by factors of ten.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-55", "question": "For most physical and chemical processes, including enzyme-catalysed reactions within the working range, the rate:", "options": ["Doubles or decreases by half for every 10 °C change in either direction", "Remains constant regardless of temperature", "Increases tenfold for every 1 °C rise", "Increases only when temperature falls"], "answer": 0, "explanation": "NCERT states that the rate of a physical or chemical process generally doubles or halves for every 10 °C change. Enzymes show this only up to their optimum; beyond it they denature.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-56", "question": "The flow of metabolites through metabolic pathways at a definite rate and direction, like automobile traffic, is called:", "options": ["The acid-insoluble pool", "The dynamic state of body constituents", "Primary structure", "The transition state"], "answer": 1, "explanation": "Metabolites are constantly converted into one another, and this flow is called the dynamic state of body constituents. The transition state is the high-energy intermediate in a single reaction.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-57", "question": "Amino acids are called substituted methanes because:", "options": ["They contain only carbon and hydrogen", "The four valency positions of the alpha carbon are occupied by hydrogen, a carboxyl group, an amino group and a variable R group", "They are formed by oxidation of methane", "They release methane on hydrolysis"], "answer": 1, "explanation": "An amino acid has an alpha carbon whose four valencies carry H, COOH, NH₂ and the R group, so it is a substituted methane. The R group determines the kind of amino acid.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-58", "question": "Coenzymes differ from prosthetic groups in that coenzymes:", "options": ["Are inorganic metal ions", "Are tightly and permanently bound to the apoenzyme", "Associate with the apoenzyme only transiently, usually during catalysis", "Are made of protein"], "answer": 2, "explanation": "Both coenzymes and prosthetic groups are organic, but a coenzyme's association with the apoenzyme is transient (during catalysis), while a prosthetic group is tightly bound. Metal ions form a third kind of cofactor.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-59", "question": "NCERT lists rubber, gums and cellulose under which category of secondary metabolites?", "options": ["Alkaloids", "Polymeric substances", "Essential oils", "Lectins"], "answer": 1, "explanation": "In NCERT's table of secondary metabolites, rubber, gums and cellulose are polymeric substances. Morphine and codeine are alkaloids; lemon grass oil is an essential oil; concanavalin A is a lectin.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-60", "question": "Arrange the following components of a typical cell in DECREASING order of their percentage of total cellular mass: (i) Proteins (ii) Lipids (iii) Nucleic acids (iv) Carbohydrates", "options": ["(i), (iii), (iv), (ii)", "(i), (iv), (iii), (ii)", "(iii), (i), (iv), (ii)", "(i), (ii), (iii), (iv)"], "answer": 0, "explanation": "NCERT gives water 70–90%, proteins 10–15%, nucleic acids 5–7%, carbohydrates 3%, lipids 2% and ions 1%. So proteins > nucleic acids > carbohydrates > lipids.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-61", "question": "Carbonic anhydrase raises the rate of H₂CO₃ formation from about 200 molecules per hour (uncatalysed) to about 600,000 molecules per second. By roughly what factor is the reaction accelerated?", "options": ["About 3,000 times", "About 180,000 times", "About 10 million times", "About 1 billion times"], "answer": 2, "explanation": "Convert to the same unit: 600,000 per second × 3600 = 2.16 × 10⁹ per hour. Divide by 200 per hour: about 1.08 × 10⁷, i.e. roughly 10 million times. Forgetting the hour-to-second conversion gives the 3,000 trap.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-62", "question": "How many of the following statements comparing the earth's crust and the human body are correct (per cent weight)?\n(i) Oxygen is the most abundant element in both.\n(ii) Carbon forms about 18.5% of the human body but only about 0.03% of the crust.\n(iii) Sodium is more abundant in the human body than in the crust.\n(iv) Silicon forms about 27.7% of the crust but is negligible in the human body.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iv) are correct: oxygen is 46.6% of the crust and 65% of the body. (iii) is wrong: sodium is about 2.8% of the crust but only 0.2% of the body.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-63", "question": "Match the bond with the molecules it joins.\nList I: (A) Peptide bond (B) Glycosidic bond (C) Phosphodiester bond (D) Ester bond in a fat\nList II: (1) Fatty acid and glycerol (2) Two monosaccharides, formed by dehydration (3) Carboxyl group of one amino acid and amino group of the next (4) Phosphate and the hydroxyl groups of sugars of adjacent nucleotides", "options": ["A-3, B-4, C-2, D-1", "A-2, B-3, C-4, D-1", "A-3, B-2, C-1, D-4", "A-3, B-2, C-4, D-1"], "answer": 3, "explanation": "A peptide bond links COOH of one amino acid to NH₂ of the next; a glycosidic bond links monosaccharides by dehydration; a phosphodiester bond links phosphate to the sugar hydroxyls of two nucleotides; fatty acids are esterified with glycerol in fats.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-64", "question": "Arrange the steps of the catalytic cycle of an enzyme in the correct order:\n(i) The active site, now close to the substrate, breaks its chemical bonds and an enzyme-product complex forms\n(ii) The enzyme releases the products and is free to bind another substrate\n(iii) The substrate binds to the active site\n(iv) Binding induces the enzyme to alter its shape, fitting more tightly around the substrate", "options": ["(iii), (iv), (i), (ii)", "(iv), (iii), (i), (ii)", "(iii), (i), (iv), (ii)", "(i), (iii), (iv), (ii)"], "answer": 0, "explanation": "The substrate first binds the active site, which induces a tighter fit; the active site then breaks the substrate's bonds forming an enzyme-product complex, and finally the products are released, freeing the enzyme.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-65", "question": "How many of the following statements about the acid-soluble and acid-insoluble fractions are correct?\n(i) The acid-insoluble fraction contains proteins, nucleic acids and polysaccharides.\n(ii) Compounds of the acid-soluble pool have molecular weights of about 18 to 800 daltons.\n(iii) Lipids are found in the acid-insoluble fraction.\n(iv) Lipids have molecular weights exceeding 10,000 daltons, which is why they are macromolecules.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iii) are correct. (iv) is wrong: the molecular weight of lipids does not exceed 800 Da; they appear in the insoluble fraction only because cell membranes break into water-insoluble vesicles on grinding, so they are not strictly macromolecules.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-66", "question": "How many of the following statements about lipids are correct?\n(i) A fatty acid has a carboxyl group attached to an R group, which may be a methyl, ethyl or higher number of -CH₂ groups.\n(ii) Palmitic acid has 16 carbon atoms including the carboxyl carbon.\n(iii) Glycerol is a dihydroxy propane.\n(iv) Some tissues, especially neural tissues, have lipids with more complex structures.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iv) are correct. (iii) is wrong: glycerol is trihydroxy propane, which is why it can esterify up to three fatty acids to form triglycerides.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-67", "question": "Assertion (A): Lipids are strictly macromolecules formed by polymerisation of fatty acids and glycerol.\nReason (R): On grinding a tissue, cell membranes break into pieces that form water-insoluble vesicles, so lipids are found in the acid-insoluble fraction.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false: lipids are small molecules (molecular weight below 800 Da) and are not polymers. R is true and explains why they nevertheless appear in the acid-insoluble fraction.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-68", "question": "Assertion (A): Competitive inhibitors are often used in the control of bacterial pathogens.\nReason (R): A competitive inhibitor closely resembles the substrate in molecular structure and competes with it for the substrate-binding site of the enzyme.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: because the inhibitor mimics the substrate and occupies the active site, it blocks a key bacterial enzyme, which NCERT notes is exploited to control bacterial pathogens.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-69", "question": "All of the following can act as cofactors of enzymes EXCEPT:", "options": ["Zinc", "Haem", "NAD", "Apoenzyme"], "answer": 3, "explanation": "Cofactors are non-protein constituents: metal ions like zinc, prosthetic groups like haem, and coenzymes like NAD. The apoenzyme is the protein part itself, so it is not a cofactor.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biomolecules-enzymes-70", "question": "Which statement about the effect of temperature and pH on enzymes is INCORRECT?", "options": ["Activity declines both below and above the optimum value", "Low temperature preserves the enzyme in a temporarily inactive state", "High temperature destroys activity because proteins are denatured by heat", "All enzymes of the human body show their highest activity at pH 7"], "answer": 3, "explanation": "Each enzyme has its own optimum pH; for example pepsin works in the acidic stomach while pancreatic enzymes work at alkaline pH. The other three statements are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-biomolecules-enzymes-71","question":"Paper made from plant pulp, and cotton fibre, are chemically:","options":["Lipid","Nucleic acid","Protein","Cellulosic"],"answer":3,"explanation":"Plant cell walls are made of cellulose, so paper made from plant pulp and cotton fibre are both cellulosic.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-72","question":"The pocket or crevice in an enzyme into which the substrate fits is called the:","options":["Prosthetic group","Cofactor","Apoenzyme","Active site"],"answer":3,"explanation":"When the protein chain folds into its tertiary structure, it forms crevices or pockets; the one the substrate fits into is the active site, where catalysis happens.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-73","question":"The most important form of energy currency in living systems is:","options":["ATP","Glucose","Pyruvic acid","Starch"],"answer":0,"explanation":"Energy released by catabolic pathways is stored as chemical bonds in ATP and used for biosynthetic, osmotic and mechanical work.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-74","question":"Amino-sugars and chemically modified sugars, such as glucosamine and N-acetyl galactosamine, are building blocks of:","options":["Nucleic acids","Lipids","Complex polysaccharides","Proteins"],"answer":2,"explanation":"Complex polysaccharides, such as chitin in the arthropod exoskeleton, contain amino-sugars and chemically modified sugars as building blocks.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-75","question":"Monoterpenes and diterpenes are secondary metabolites classed as:","options":["Alkaloids","Toxins","Lectins","Terpenoides"],"answer":3,"explanation":"Monoterpenes and diterpenes are terpenoides. Morphine and codeine are alkaloids, concanavalin A is a lectin, and abrin and ricin are toxins.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-76","question":"Inorganic catalysts differ from most enzymes in that inorganic catalysts:","options":["Work efficiently at high temperatures and high pressures","Are always proteins","Are damaged above about 40 degrees C","Act only inside living cells"],"answer":0,"explanation":"Inorganic catalysts work efficiently at high temperatures and pressures, whereas most enzymes are damaged above about 40 degrees C. Enzymes from thermophilic organisms are an exception.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-77","question":"Which of the following proteins acts as a hormone?","options":["Trypsin","Collagen","GLUT-4","Insulin"],"answer":3,"explanation":"Insulin is a protein hormone. Trypsin is an enzyme, collagen forms the intercellular ground substance, and GLUT-4 transports glucose into cells.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-78","question":"The rate of a physical or chemical process refers to:","options":["The total amount of product formed at the end","The amount of enzyme used per unit time","The amount of product formed per unit time","The temperature at which the reaction stops"],"answer":2,"explanation":"Rate is the amount of product formed per unit time; it can also be expressed as the change in a quantity divided by time.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-79","question":"A glycerol molecule in which two of its hydroxyl groups are esterified with fatty acids is called a:","options":["Monoglyceride","Phospholipid","Triglyceride","Diglyceride"],"answer":3,"explanation":"Glycerol (trihydroxy propane) esterified with one, two or three fatty acids gives monoglycerides, diglycerides and triglycerides, respectively.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-80","question":"An enzyme converts glucose-6-phosphate into its positional isomer fructose-6-phosphate. This enzyme belongs to the class:","options":["Lyases","Isomerases","Transferases","Ligases"],"answer":1,"explanation":"Isomerases interconvert optical, geometric or positional isomers. Lyases remove groups leaving double bonds, transferases move a group between substrates, and ligases join two compounds.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-81","question":"Within its working range, an enzyme-catalysed reaction doubles in rate for every 10 degrees C rise in temperature. If the rate at 20 degrees C is R, the rate at 40 degrees C will be about:","options":["2R","4R","8R","R/2"],"answer":1,"explanation":"From 20 to 30 degrees C the rate doubles to 2R, and from 30 to 40 degrees C it doubles again, to 4R.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-82","question":"How many water molecules are released when a linear polypeptide of 51 amino acids is formed from free amino acids?","options":["51","52","50","102"],"answer":2,"explanation":"Each peptide bond forms by dehydration, releasing one water molecule. A linear chain of 51 amino acids has 50 peptide bonds, so 50 water molecules are released.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-83","question":"Which statement about metabolic reactions in living systems is correct?","options":["Some metabolic conversions proceed without any catalyst","Anabolic pathways release energy","Metabolic reactions always occur in isolation","Even CO2 dissolving in water, a physical process, is a catalysed reaction in living systems"],"answer":3,"explanation":"There is no uncatalysed metabolic conversion in living systems, and even the dissolving of CO2 is catalysed, by carbonic anhydrase. Most metabolic reactions are linked to other reactions, and anabolic pathways consume energy.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-84","question":"Glucose is first converted to pyruvic acid. During fermentation in yeast, this pyruvic acid is finally converted to:","options":["Ethanol","Lactic acid","Glycogen","Cholesterol"],"answer":0,"explanation":"In yeast fermentation the end product is ethanol. Skeletal muscle under anaerobic conditions makes lactic acid, and under aerobic conditions pyruvic acid is broken down further in respiration.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-85","question":"The active site of an enzyme is a pocket formed when the protein backbone folds upon itself and criss-crosses. This pocket is a feature of the protein's:","options":["Primary structure","Secondary structure only","Tertiary structure","Peptide bonds"],"answer":2,"explanation":"In the tertiary structure the chain folds upon itself, creating many crevices or pockets, one of which is the active site. The primary structure is only the amino acid sequence.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-86","question":"The sugar in DNA, 2'-deoxyribose, differs from ribose in lacking an oxygen atom at carbon:","options":["1'","2'","3'","5'"],"answer":1,"explanation":"As its name shows, 2'-deoxyribose has no oxygen (hydroxyl) at the 2' carbon. The 3' and 5' carbons take part in phosphodiester bonds.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-87","question":"In a polynucleotide chain, the phosphate of a phosphodiester bond links:","options":["The 3'-carbon of one sugar to the 5'-carbon of the next sugar","The 1'-carbon of one sugar to the base of the next nucleotide","Two nitrogenous bases of the same strand","The 2'-carbon of one sugar to the 2'-carbon of the next sugar"],"answer":0,"explanation":"The phosphate links the 3'-carbon of one nucleotide's sugar to the 5'-carbon of the next nucleotide's sugar. The base is attached to the 1'-carbon by a glycosidic bond.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-88","question":"An oxidoreductase catalyses the reaction: S (reduced) + S' (oxidised) → S (oxidised) + S' (reduced). Which statement about this reaction is correct?","options":["S loses hydrogen (electrons) and is oxidised, while S' is reduced","S' loses hydrogen and is oxidised, while S is reduced","Both S and S' are oxidised","A group G other than hydrogen is transferred from S to S'"],"answer":0,"explanation":"S starts reduced and ends oxidised, so it is the hydrogen donor; S' accepts the hydrogen and is reduced. Moving a group other than hydrogen is what transferases do.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-89","question":"Match the compound with its category.\nList I: (A) Lecithin (B) Uridine (C) Inulin (D) Codeine\nList II: (1) Homopolymer of fructose (2) Phospholipid (3) Alkaloid (4) Nucleoside","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3"],"answer":2,"explanation":"Lecithin is a phospholipid, uridine is a nucleoside (uracil plus ribose, with no phosphate), inulin is a polymer of fructose, and codeine is an alkaloid.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-90","question":"Proteins are made of 20 types of amino acids. How many different linear tripeptides are theoretically possible if any amino acid can occupy any position, repeats are allowed and the order matters?","options":["60","1,140","400","8,000"],"answer":3,"explanation":"Each of the three positions can be filled in 20 ways, so 20 × 20 × 20 = 8,000 tripeptides are possible. This shows how sequence alone can create huge diversity in proteins.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-91","question":"A linear double-stranded DNA molecule is 1,000 base pairs long. How many phosphodiester bonds does it contain in its sugar-phosphate backbones?","options":["999","1,000","1,998","2,000"],"answer":2,"explanation":"Each strand has 1,000 nucleotides joined by 999 phosphodiester bonds, so the two strands together have 2 × 999 = 1,998 bonds. A circular molecule would have 2,000.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-92","question":"For an enzyme obeying Michaelis-Menten kinetics, at what substrate concentration does the reaction velocity reach 90 per cent of Vmax?","options":["9 Km","0.9 Km","Km","90 Km"],"answer":0,"explanation":"v = Vmax[S]/(Km + [S]). Setting v = 0.9 Vmax gives [S] = 0.9 Km + 0.9 [S], so 0.1 [S] = 0.9 Km and [S] = 9 Km.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-93","question":"A triglyceride is formed by esterifying glycerol with three molecules of palmitic acid. How many carbon atoms does this triglyceride contain?","options":["48","54","19","51"],"answer":3,"explanation":"Palmitic acid has 16 carbons (including the carboxyl carbon) and glycerol has 3. Esterification does not remove carbon, so the total is 3 × 16 + 3 = 51.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-94","question":"From the following list, how many are nucleotides?\nAdenosine, uridylic acid, guanosine, cytidylic acid, thymidine, adenylic acid, uracil","options":["Two","Three","Four","Five"],"answer":1,"explanation":"Uridylic acid, cytidylic acid and adenylic acid have a phosphate, so they are nucleotides. Adenosine, guanosine and thymidine are nucleosides (base plus sugar), and uracil is just a base.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-95","question":"Match the enzyme with its class.\nList I: (A) Hexokinase, which moves a phosphate group from ATP to glucose (B) Lactate dehydrogenase (C) Lipase, which breaks ester bonds of fats with water (D) DNA ligase, which joins two DNA fragments\nList II: (1) Hydrolase (2) Oxidoreductase (3) Ligase (4) Transferase","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-4, B-1, C-2, D-3","A-3, B-2, C-1, D-4"],"answer":0,"explanation":"Moving a group other than hydrogen is a transferase reaction, a dehydrogenase is an oxidoreductase, breaking an ester bond with water is hydrolysis, and joining two molecules with a new bond is the work of a ligase.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-96","question":"From the following list of conversions, how many are catabolic?\nGlucose to lactic acid; acetic acid to cholesterol; amino acids to a protein; starch to glucose; glucose to pyruvic acid; nucleotides to a nucleic acid","options":["Two","Four","Three","Five"],"answer":2,"explanation":"Glucose to lactic acid, starch to glucose and glucose to pyruvic acid break down complex molecules and are catabolic. Making cholesterol, proteins and nucleic acids is anabolic (biosynthetic).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-97","question":"A protein has four polypeptide chains of 140, 140, 145 and 145 amino acids. How many peptide bonds does the whole protein contain?","options":["570","566","569","574"],"answer":1,"explanation":"A chain of n amino acids has n - 1 peptide bonds: 139 + 139 + 144 + 144 = 566. The chains of a quaternary protein are held together by other interactions, not peptide bonds.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-98","question":"From the following list, how many are secondary metabolites?\nCarotenoids, morphine, lemon grass oil, concanavalin A, glucose, amino acids, curcumin, rubber","options":["Four","Five","Six","Seven"],"answer":2,"explanation":"Carotenoids (pigment), morphine (alkaloid), lemon grass oil (essential oil), concanavalin A (lectin), curcumin (drug) and rubber (polymeric substance) are secondary metabolites. Glucose and amino acids are primary metabolites.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-99","question":"Match the level of protein structure with its description.\nList I: (A) Primary (B) Secondary (C) Tertiary (D) Quaternary\nList II: (1) Arrangement of two or more polypeptide subunits relative to one another (2) The chain folded upon itself like a hollow woollen ball (3) The sequence of amino acids (4) Parts of the chain folded into a helix, only right-handed in proteins","options":["A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1"],"answer":3,"explanation":"Primary structure is the amino acid sequence, secondary includes right-handed helices, tertiary is the three-dimensional folding like a woollen ball, and quaternary is the arrangement of subunits, as in adult haemoglobin (2 alpha + 2 beta).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biomolecules-enzymes-100","question":"From the following elements, how many make up a greater percentage of weight in the human body than in the earth's crust?\nHydrogen, carbon, oxygen, nitrogen, sulphur, sodium, calcium, magnesium, silicon","options":["Four","Five","Six","Seven"],"answer":1,"explanation":"Hydrogen (0.5 vs 0.14), carbon (18.5 vs 0.03), oxygen (65.0 vs 46.6), nitrogen (3.3 vs very little) and sulphur (0.3 vs 0.03) are richer in the body. Sodium, calcium, magnesium and silicon are richer in the crust.","difficulty":"very-hard","source":"NEET pattern"},
];

export default questions;
